  if [ "$apply" = 1 ]; then contexts=$(checks '.github' 'main'); else contexts='[{"context":"<each job a pull request reports, read when applied>"}]'; fi
  if [ "$contexts" = "[]" ]; then echo "UOR-Foundation/.github: no unfiltered pull_request jobs; required status checks not set" >&2; rules='[{"type":"pull_request","parameters":{"required_approving_review_count":1,"dismiss_stale_reviews_on_push":false,"require_code_owner_review":false,"require_last_push_approval":false,"required_review_thread_resolution":false}},{"type":"non_fast_forward"}]';
  else rules=$(jq -c --argjson c "$contexts" '. + [{type: "required_status_checks", parameters: {strict_required_status_checks_policy: false, required_status_checks: $c}}]' <<<'[{"type":"pull_request","parameters":{"required_approving_review_count":1,"dismiss_stale_reviews_on_push":false,"require_code_owner_review":false,"require_last_push_approval":false,"required_review_thread_resolution":false}},{"type":"non_fast_forward"}]'); fi
  jq -c --argjson r "$rules" '.rules = $r' <<<'{"name":"governance-6.2-t3","target":"branch","enforcement":"active","conditions":{"ref_name":{"include":["~DEFAULT_BRANCH"],"exclude":[]}},"rules":[{"type":"pull_request","parameters":{"required_approving_review_count":1,"dismiss_stale_reviews_on_push":false,"require_code_owner_review":false,"require_last_push_approval":false,"required_review_thread_resolution":false}},{"type":"non_fast_forward"}]}' | ruleset '.github' 'governance-6.2-t3'
fi
